VALUES ('c25b1096-d7c6-566c-9e85-af3a5c2c1e42', '6575a2f9-8a4c-5456-877b-d5a067f248b3', 'state_province_id', 'State Province', 'The state, province or equivalent division the address is in. Chosen after the country, from that country''s divisions. At most one; some countries have no divisions in the list. Must belong to the address''s own country. Must be a division of the address''s own country.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4911a117-69ba-597a-837d-e51aafde3c69', '6575a2f9-8a4c-5456-877b-d5a067f248b3', 'city_id', 'City', 'The city the address is in, chosen from the list. Chosen after the state or province; use the city name field only when the city is not listed. At most one. Must belong to the address''s own country, and to its state or province where one is given. Must be a city of the address''s own country, and of its state or province where one is stated.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 170, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
