VALUES ('f17777f3-b50b-5b9f-8a7e-293e26039d1a', '3861f737-e477-5707-aeca-8d97cd87b446', '6151fbbd-7f46-5be9-bc04-cdd824a251f4', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'The permanent system identity of the address. Generated on creation; parties, locations and document snapshots refer to the address through it. Must be unique: a save is rejected if another Address already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
