VALUES ('dd5547d0-4f7c-5ba5-bd29-083c984d13ea', '641ab32f-e82c-575d-aca4-4faee311178e', '45cc67b9-6878-5ade-b536-6d8457247f31', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'Stable identity of the unit-of-measure definition. Referenced by Product, transaction lines, inventory, and conversion rules. Identifies the measurement definition rather than a quantity value. Allows every quantity-bearing workflow to resolve exactly how a numeric quantity must be interpreted. Must be unique: a save is rejected if another Unit Of Measure already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('10a8a4e9-9c91-562b-94d0-729fbc0f2f47', '641ab32f-e82c-575d-aca4-4faee311178e', '28a5daa5-7698-55ca-b21d-c77a4408d70a', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Code', 'Standard business code for the unit, such as EACH, KG, L, HOUR, or DAY. Used in forms, integrations, documents, validation, and quantity display. Code identifies the unit definition; it does not represent a conversion or quantity itself. Used to resolve units during order entry, purchasing, receipt, inventory, invoicing, and reporting. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Unit Of Measure already uses this value. Up to 30 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b0822946-c9aa-52de-aaad-458eac1b19b3', '641ab32f-e82c-575d-aca4-4faee311178e', '043cf27a-cd31-5e8c-b2ca-b74ac5f8f6e3', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Name', 'Human-readable name of the measurement unit. Used in user interfaces, reports, documents, catalogs, and search. Describes the unit definition identified by code and unitOfMeasureId. Provides understandable measurement context to business users. Required — the record cannot be saved while this is empty. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e6452f61-5208-553d-b16f-86522192417e', '641ab32f-e82c-575d-aca4-4faee311178e', '3eec2f43-63ad-5750-9dde-378a231cbdbc', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Symbol', 'Standard display symbol for the unit. Used for compact display in documents, labels, reports, and interfaces. Symbol is presentation metadata and does not replace the canonical unit code. Improves human-readable representation of quantities. Up to 20 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
