VALUES ('3578a017-4a94-516c-a352-321a9dc75261', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'shipment_number', 'Shipment Number', 'Read with the carrier''s reference to follow a delivery. Unique; quoted to carriers and customers. The shipment number of the shipment: a value the business records on it.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
