INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('760cb817-3e98-59c4-8c17-64ba81c98422', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'shipment_type', 'Shipment Type', 'The direction of the movement. Chosen when the shipment is created; decides which orders can link. Read with the origin and destination. Goods arriving from a supplier. Goods going to a customer. Goods moving between the business''s own locations. Goods coming back from a customer or going back to a supplier.', 1059, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c677c7b-24d0-5b53-b57d-4b3b2a477565', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'status', 'Status', 'The operational stage of the shipment, from planning through booking, transit and delivery, or to exception or cancellation. Starts as PLANNED and moves as logistics staff book, dispatch and deliver; it controls tracking and downstream fulfilment, not stock. The shipment is being prepared; no carrier has been booked and nothing has left the origin. A carrier and a slot are confirmed, but the goods have not yet left the origin. The goods have been dispatched and are travelling between origin and destination. The goods arrived at the destination and delivery was confirmed. A final state. The shipment was called off before completion and will not move. A final state. Something has gone wrong, such as a delay, damage or a refused delivery, and the shipment needs attention before it continues. Status is not inventory status and does not itself prove customer acceptance or invoice payment. Drives permitted logistics transitions and downstream fulfillment/movement workflows.', 1060, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
