VALUES ('44169cbf-2540-5dea-9286-37a74982bf02', 'ce5151d4-2613-5066-9cb3-90bc1d549248', 'id', 'Id', 'The identity of the order, constant for its life. Generated on creation; shipments and invoices refer to it. Referenced by every document that follows the order.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
