VALUES ('3c6790d2-345f-5cce-96b6-dd608d83c7e3', '5990f296-d406-5b61-b218-856ca3029bcb', 'party_id', 'Party', 'Party associated with inventory event when ownership or custody matters. Supplier receipts, customer returns, consignment and audit. Optional for internal movements. Connects event to external party.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
