-- --------------------------------------------------------------------------
-- Carrier (bus_carrier)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8526590-b65c-5f19-9525-23db73fcfc2e', 'Carrier', 'Maintain Carrier records', 'Create, find and maintain Carrier records. The list shows every Carrier you have access to — select a row to open it, or use New to add one. Each row is a single Carrier, described by 11 fields.

Id is unique: no two Carrier records may share the same value, and a save that would duplicate one is rejected. Name, Carrier Type, Status and Party must be filled in before the record can be saved.

Every Carrier points at Party. Choose the linked record from the lookup on those fields rather than typing an identifier. Shipment, Consignment, Freight Charge, Load and Route refer back to Carrier, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Carrier then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Carrier with no rules or workflows attached is marked Final immediately.', 'truck', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('407b94b6-86ed-58e7-9256-bf5f261167d1', 'bus_carrier', 'Carrier', 'A logistics provider that transports shipments, consignments or loads. Goods usually move on someone else''s trucks, ships or planes. A carrier record identifies that provider and gives bookings, tracking and freight invoices a single party to refer to. Created when a transport provider is approved for use; selected when shipments are booked; read for service performance and freight costs. A carrier is a Party acting in the transport role; shipments and consignments are assigned to it. Changes and retries preserve history, and a carrier''s past shipments remain linked to it after it stops being used. A regional haulage firm engaged for pallet deliveries within the country.', 'truck', 'A', FALSE, FALSE, FALSE, TRUE, 'c8526590-b65c-5f19-9525-23db73fcfc2e', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b8ff063e-aa63-5768-a857-e3e06ac528fe', 'c8526590-b65c-5f19-9525-23db73fcfc2e', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'Carrier', 'Shows one Carrier at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4978e89-8d1d-5458-9a65-19d8f5c6dfa2', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'id', 'Id', 'The identity of the carrier role. Generated on creation; shipments and rates refer to the carrier through it.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8ac68aaf-621e-588a-bbcd-a89578bc3287', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'code', 'Code', 'The carrier''s short code, such as the SCAC code used in North American freight. Entered when the carrier is set up; used on shipping documents and in EDI messages.', 10, 120, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5848f4ab-5142-57af-8f5a-f55fadc8d5f4', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'name', 'Name', 'The name the carrier trades under, as dispatchers and planners know it. Shown wherever a carrier is chosen for a booking or consignment. The legal name is held on its party record.', 10, 200, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c0604ed9-e5dc-5b34-bdb9-8f8709877e53', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'carrier_type', 'Carrier Type', 'What kind of transport service the carrier mainly provides, such as road, rail or air. Planners filter the carriers they can book by it when choosing for a consignment. A carrier offering several modes is recorded with its main one. Road haulage, full or part loads. Parcel and courier networks. Rail freight operators moving wagons or containers by train. Shipping lines carrying containers or bulk cargo by sea. Airlines and air cargo carriers. A freight forwarder arranging transport with other carriers.', 1006, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4ddd34e2-c550-5a30-a20b-237083a5b3f8', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'scac', 'Scac', 'The Standard Carrier Alpha Code, used in North American and ocean documents. Printed on bills of lading and used in EDI. Four letters.', 10, 4, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('90392f03-1bdd-55cc-a8c5-3b99cd1583e5', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'iata_code', 'Iata Code', 'The carrier''s two or three character IATA airline code, for air carriers only. Printed on air waybills and used to match the carrier in airline schedules. Left empty for carriers that are not airlines.', 10, 3, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d74d3356-f8d8-5703-a171-4ee58ab3f29c', '407b94b6-86ed-58e7-9256-bf5f261167d1', 'insurance_expiry_date', 'Insurance Expiry Date', 'When the carrier''s liability insurance certificate expires. Watched so that bookings stop with uninsured carriers. A new certificate must be received before it.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
