-- --------------------------------------------------------------------------
-- Consignment (bus_consignment)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('811736d0-f49f-5304-a15b-69ef7cf8efc4', 'Consignment', 'Maintain Consignment records', 'Create, find and maintain Consignment records. The list shows every Consignment you have access to — select a row to open it, or use New to add one. Each row is a single Consignment, described by 17 fields.

Id is unique: no two Consignment records may share the same value, and a save that would duplicate one is rejected. Transport Mode and Status must be filled in before the record can be saved.

Every Consignment points at Carrier and Shipment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Consignment then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Consignment with no rules or workflows attached is marked Final immediately.', 'file-text', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('df21668f-71e1-5a00-a879-c5cbc73efc9b', 'bus_consignment', 'Consignment', 'A grouping of goods handed to a carrier under common transport responsibility and commercial terms. A consignment is what the carrier is actually asked to move: one set of goods, from one sender, under one contract of carriage. It is the unit that is tracked, insured and billed. Created when goods are tendered to a carrier; tracked until delivery; read for status, proof of delivery and freight charges. A consignment is carried by a Carrier and contains one or more shipments. Changes and retries keep history and do not duplicate the commercial, physical or financial effects of the consignment. Twelve pallets for three customers consolidated onto one truck to a regional depot under a single waybill.', 'file-text', 'A', FALSE, FALSE, FALSE, TRUE, '811736d0-f49f-5304-a15b-69ef7cf8efc4', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8c283321-23e7-5ce1-add8-c6b919d147ca', '811736d0-f49f-5304-a15b-69ef7cf8efc4', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'Consignment', 'Shows one Consignment at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Carrier and Shipment are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
