ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('253cd998-198f-59c4-a83f-06ea80dfeb3c', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'code', 'Code', 'The consignment or waybill number given to the grouping. Used by the carrier and customer to track and reference the movement.', 10, 120, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f381bc8b-5248-5200-a38e-ba6c2ebab0fd', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'transport_document_number', 'Transport Document Number', 'The number of the waybill, bill of lading or consignment note issued for the goods. Entered when the carrier issues the document; tracking and freight invoices quote it. Issued by the carrier, so it is known only after booking.', 10, 60, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9ae93d96-3cfc-5541-967a-2c2b24dd3021', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'transport_mode', 'Transport Mode', 'By truck or van. By train, on a rail freight service. By ship, on a vessel or container service. By aircraft, as air cargo. By a parcel or courier network. By more than one mode under one contract. How the goods travel. Chosen when booking; it decides which transport document is used and which rules apply. A multimodal journey is recorded as its main mode, with the legs as trip segments.', 1009, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4c5ed98c-101c-50eb-af80-841b4e70bae8', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'service_level', 'Service Level', 'The carrier''s service ordered, such as "Express 24h" or "Groupage". Chosen when booking; it sets the promised transit time and the price. The carrier''s own name for the service.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2fc3055c-d7a6-5e54-8838-714f2025063f', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'incoterm', 'Incoterm', 'The Incoterms rule that says who pays and bears risk for the carriage, such as DAP or FCA. Copied from the order; it decides whether the freight charge is ours or the customer''s. Three-letter Incoterms 2020 code.', 10, 3, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f4a90914-a38c-5143-aed0-6be9623042cf', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'package_count', 'Package Count', 'How many packages, pallets or pieces the carrier accepted. Counted at hand-over and printed on the transport document. Must match the labels; a shortfall on delivery is a claim.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
