INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bd530b9c-4ae1-503d-9992-94199640ee2a', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'planned_pickup_at', 'Planned Pickup At', 'When the carrier is due to collect the goods. Agreed at booking; the warehouse plans dispatch around it. Must not be later than the planned delivery.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
