VALUES ('5c8f6702-af66-5fe2-942a-9607a5466dd8', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'planned_delivery_at', 'Planned Delivery At', 'When the goods are due at the destination. Promised by the carrier for the service ordered; customer delivery dates rely on it. Late delivery is measured against it.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
