VALUES ('9057d38f-c976-561c-b6c3-b2cda533d603', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'delivered_at', 'Delivered At', 'The date and time the goods were actually handed over at their destination. Taken from the proof of delivery and used to measure on-time performance. Present once the consignment is delivered.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
