INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('484f80f7-675b-5445-a810-ebf659846cea', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'status', 'Status', 'Where the consignment is between planning and delivery. Moved on by booking, hand-over, tracking updates and the proof of delivery. An exception needs someone to act before the consignment can continue. Put together but not yet booked with a carrier. Booked; the carrier has confirmed collection. Collected by the carrier and on its way. Delivered and signed for at the destination. The carrier reported a problem, such as damage, a failed delivery or a hold at customs. Called off before the carrier collected it.', 1008, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('89dadafc-8e66-5689-a7e3-e793a5805562', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'carrier_id', 'Carrier', 'The transport company that carries the goods. Chosen when booking; its service, documents and invoice apply to the consignment. One carrier per consignment; a change of carrier means a new consignment. Subcontracted legs stay the carrier''s responsibility.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7ac2e640-dfa1-523c-8960-0b2d5181b8f2', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'shipment_id', 'Shipment', 'The shipment whose goods the consignment carries. Linked when the consignment is built from a shipment. The main shipment; consolidated consignments name their first shipment and list the rest in the notes. The shipment''s status follows the consignment''s.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e19b627b-d474-5c1c-98d2-64971a554416', 'df21668f-71e1-5a00-a879-c5cbc73efc9b', 'origin_id', 'Origin', 'Where the carrier collects the goods. Taken from the shipment or the warehouse dispatching it. One origin per consignment. Printed as the shipper''s address on the transport document.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 170, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
