VALUES ('46312e40-a61a-5b6e-9c7f-21b87f43de3c', '8c283321-23e7-5ce1-add8-c6b919d147ca', '253cd998-198f-59c4-a83f-06ea80dfeb3c', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Code', 'The consignment or waybill number given to the grouping. Used by the carrier and customer to track and reference the movement. Up to 120 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8aa74055-a853-55ac-852d-016b30e4108f', '8c283321-23e7-5ce1-add8-c6b919d147ca', 'f381bc8b-5248-5200-a38e-ba6c2ebab0fd', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Transport Document Number', 'The number of the waybill, bill of lading or consignment note issued for the goods. Entered when the carrier issues the document; tracking and freight invoices quote it. Issued by the carrier, so it is known only after booking. Up to 60 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('48402048-2c75-5c14-bcbd-a71e422ea8b6', '8c283321-23e7-5ce1-add8-c6b919d147ca', '9ae93d96-3cfc-5541-967a-2c2b24dd3021', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Transport Mode', 'By truck or van. By train, on a rail freight service. By ship, on a vessel or container service. By aircraft, as air cargo. By a parcel or courier network. By more than one mode under one contract. How the goods travel. Chosen when booking; it decides which transport document is used and which rules apply. A multimodal journey is recorded as its main mode, with the legs as trip segments. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
