-- --------------------------------------------------------------------------
-- Delivery (bus_delivery)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c4b29932-a503-56c2-bbbe-33d9119d6656', 'Delivery', 'Maintain Delivery records', 'Create, find and maintain Delivery records. The list shows every Delivery you have access to — select a row to open it, or use New to add one. Each row is a single Delivery, described by 10 fields.

Id is unique: no two Delivery records may share the same value, and a save that would duplicate one is rejected. Delivered At, Outcome and Shipment must be filled in before the record can be saved.

Every Delivery points at Shipment and Location. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Delivery then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Delivery with no rules or workflows attached is marked Final immediately.', 'truck', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'bus_delivery', 'Delivery', 'The record that shipped goods were handed over to a destination or recipient. A shipment is not finished when it leaves; it is finished when someone receives it. The delivery is the proof of that handover, which settles disputes and triggers invoicing. Created when the carrier confirms handover; read by customer service, finance and claims. Each delivery belongs to one Shipment and records its final handover. Changes and retries preserve the evidence and never duplicate downstream effects such as invoicing. Pallet delivery signed for by the receiving clerk at 14:20 on Thursday.', 'truck', 'A', FALSE, FALSE, FALSE, TRUE, 'c4b29932-a503-56c2-bbbe-33d9119d6656', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a6cc8f22-fcb1-560c-81de-f79b444b4494', 'c4b29932-a503-56c2-bbbe-33d9119d6656', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'Delivery', 'Shows one Delivery at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Shipment and Location are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
