INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c761a2db-c3ef-54e8-acb9-d27bfcdfc9f7', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'delivered_at', 'Delivered At', 'The date and time the goods were actually handed over to the recipient. Taken from the signed proof of delivery rather than typed in by hand. The legal delivery time used for invoicing and claims.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
