INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('624910b8-07c2-532d-9980-b9a881b41d15', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'received_by', 'Received By', 'The name of the person who accepted the goods. Taken from the signature on the proof of delivery. Should be someone authorised at the destination.', 10, 200, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
