INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0957b93a-fcf7-5d3b-967e-57f92e2e67a0', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'outcome', 'Outcome', 'How the handover went, as recorded on the proof of delivery. Set from the proof of delivery by the carrier or driver, and read by customer service when something went wrong. Any outcome other than a clean delivery opens a claim or a follow-up with the customer. Handed over complete and in good condition. Handed over but short, over or damaged, so a claim or note is needed. The recipient declined to accept the goods and they return to the sender.', 1019, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e163b675-7fb4-537e-8a4e-80522156e450', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'packages_delivered', 'Packages Delivered', 'The number of packages or pallets actually handed over at the destination. Counted by the driver at handover and compared with the shipment''s expected count to spot shortages. A difference from the shipment count is treated as an exception.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6991c40e-80f4-5678-a5ec-ed0efb3479da', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'condition_notes', 'Condition Notes', 'Remarks on the goods'' condition made at hand-over. Written by the driver or recipient; evidence for claims. Remarks not made at delivery are hard to claim later.', 14, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
