INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0aa090fb-2e91-5154-8cea-fc1734906bc3', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'proof_reference', 'Proof Reference', 'The reference of the proof of delivery — signed note, photo or electronic signature. Linked so the proof can be produced on request. Files are attached to the delivery.', 10, 200, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
