INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cb8ba6ec-6873-56a5-956b-6248e9bcdc98', 'e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'shipment_id', 'Shipment', 'Exactly one shipment: a delivery is the final handover of a single shipment. Shipment observed by this event. Connects logistics evidence to transport transaction. Tracking and delivery proof. Event must not silently rewrite prior shipment evidence.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
