-- --------------------------------------------------------------------------
-- Delivery Attempt (bus_delivery_attempt)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('268ae01c-c4e8-59cc-9da6-8ac6945dd23f', 'Delivery Attempt', 'Maintain Delivery Attempt records', 'Create, find and maintain Delivery Attempt records. The list shows every Delivery Attempt you have access to — select a row to open it, or use New to add one. Each row is a single Delivery Attempt, described by 10 fields.

Id is unique: no two Delivery Attempt records may share the same value, and a save that would duplicate one is rejected. Attempt Number, Attempted At, Result, Message and Endpoint must be filled in before the record can be saved.

Every Delivery Attempt points at Message. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Delivery Attempt then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Delivery Attempt with no rules or workflows attached is marked Final immediately.', 'truck', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ea4e31b3-68ff-5f57-8f1c-dff79ada566e', 'bus_delivery_attempt', 'Delivery Attempt', 'An immutable record of one attempt to deliver a message or event payload to an integration endpoint. Integrations fail and retry. Recording each attempt, with its outcome, lets operators see what was tried, diagnose failures and prove a message was delivered. Written automatically for each attempt; read by integration operators and in incident reviews. Each attempt links a Message and the IntegrationEndpoint it was sent to. An attempt is final once recorded; the next try is a new attempt. Retries must not duplicate business effects downstream. Attempt 2 to post an order event to a partner''s endpoint timed out after 30 seconds. Used for event publication, message exchange, delivery, retry, reconciliation, integration operations, and audit.', 'truck', 'A', FALSE, FALSE, FALSE, TRUE, '268ae01c-c4e8-59cc-9da6-8ac6945dd23f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('57fb49fe-a816-5b4f-9c2b-f9872a464fdc', '268ae01c-c4e8-59cc-9da6-8ac6945dd23f', 'ea4e31b3-68ff-5f57-8f1c-dff79ada566e', 'Delivery Attempt', 'Shows one Delivery Attempt at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Message is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
