VALUES ('4973370c-212d-5049-8883-cd40e83362dc', 'ea4e31b3-68ff-5f57-8f1c-dff79ada566e', 'attempt_number', 'Attempt Number', 'Which try this was for the message — 1 for the first. Set by the integration layer. Unique within the message.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
