VALUES ('9cadce8c-c355-54c4-a7aa-56ec23bb1abb', 'ea4e31b3-68ff-5f57-8f1c-dff79ada566e', 'attempted_at', 'Attempted At', 'The date and time this attempt to deliver the payload was made. Stamped by the integration layer when the attempt starts, so support staff can reconstruct the order of events. A message''s attempts are listed in this order.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
