INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('aa00743d-7944-5be9-87f8-fc13c44e53b5', 'ea4e31b3-68ff-5f57-8f1c-dff79ada566e', 'result', 'Result', 'What came of this attempt to deliver the payload to the endpoint. Set from the endpoint''s response; operators filter on it when diagnosing a delivery problem. Rejected messages are not retried, while failed and timed-out ones are tried again. The endpoint accepted the message and no further attempt is needed. The endpoint refused the message as invalid, so retrying will not help. The endpoint could not be reached or answered with an error, so the message can be retried. The endpoint did not answer in time, so the outcome is unknown and a retry is allowed.', 1018, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
