INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bc373151-8a41-511e-9313-3fc495658ddf', '5019675d-3bcb-584c-88df-d9062ec728bf', 'charge_type', 'Charge Type', 'What the charge is for. Chosen when recording it; reports group transport cost by it. Surcharges are often a percentage of base freight. The basic transport price. An adjustment for fuel prices. An extra service, such as a tail lift, waiting time or a delivery appointment. Customs duty or import tax paid by the carrier for us. A fee for keeping a container or vehicle too long. Any other transport charge.', 1024, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
