VALUES ('66793ad3-fdd5-5274-b990-35133600fe3f', '5019675d-3bcb-584c-88df-d9062ec728bf', 'expected_amount', 'Expected Amount', 'What the charge should be under the agreed rates. Computed when the shipment is rated; the audit compares the invoice with it. Empty when there is no agreed rate.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
