-- --------------------------------------------------------------------------
-- Load (bus_load)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ff8d99d2-928d-59d4-bc5b-6a1afe541d4f', 'Load', 'Maintain Load records', 'Create, find and maintain Load records. The list shows every Load you have access to — select a row to open it, or use New to add one. Each row is a single Load, described by 16 fields.

Id is unique: no two Load records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Load points at Carrier and Trip. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Load then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Load with no rules or workflows attached is marked Final immediately.', 'file-text', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4eaae194-4850-57ef-9936-90850ca10fea', 'bus_load', 'Load', 'A grouping of shipments, consignments, handling units or containers that are assigned together to one transport execution. Freight moves in loads, not in single orders. Grouping what travels together lets the carrier, the dock and the customer see one planned movement and track it as such. Created by transport planning; filled as shipments are assigned; handed to a carrier; read by dispatch and the warehouse. A load groups Shipments and Consignments under one carrier movement. Changes and retries preserve history and do not duplicate commercial, physical or financial effects. A full trailer carrying eight pallets for four customers from the central warehouse to a regional depot.', 'file-text', 'A', FALSE, FALSE, FALSE, TRUE, 'ff8d99d2-928d-59d4-bc5b-6a1afe541d4f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', 'ff8d99d2-928d-59d4-bc5b-6a1afe541d4f', '4eaae194-4850-57ef-9936-90850ca10fea', 'Load', 'Shows one Load at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Carrier and Trip are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
