INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4de91ad4-f96f-5e8a-a374-f745745ccaee', '4eaae194-4850-57ef-9936-90850ca10fea', 'vehicle_type', 'Vehicle Type', 'The type of vehicle or container the load is planned for, such as "13.6 m curtainsider" or "40ft high cube". Chosen when planning; it sets the capacity the load must fit. The carrier provides a vehicle of this type.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5aff62a7-8cd0-5046-8edf-9016fcf4c8f9', '4eaae194-4850-57ef-9936-90850ca10fea', 'max_weight_kg', 'Max Weight Kg', 'The most weight the vehicle can carry, in kilograms. Taken from the vehicle type; the load must not exceed it. Legal limits apply as well as the vehicle''s.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3ef5074a-d39b-5565-8a62-e113e8d23d4b', '4eaae194-4850-57ef-9936-90850ca10fea', 'max_volume_m3', 'Max Volume M3', 'The most volume the vehicle can hold, in cubic metres. Taken from the vehicle type. Pallet footprint often limits before volume does.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5350be61-b048-5280-834e-472a4c592257', '4eaae194-4850-57ef-9936-90850ca10fea', 'planned_weight_kg', 'Planned Weight Kg', 'The total weight of what is assigned to the load. Summed from the consignments and handling units. Must not exceed the maximum weight.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('45eacf42-4352-5428-be03-4febb7ac431c', '4eaae194-4850-57ef-9936-90850ca10fea', 'planned_volume_m3', 'Planned Volume M3', 'The total volume of what is assigned to the load. Summed from the consignments and handling units. Should not exceed the maximum volume.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
