INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a1e82568-eb30-54f9-b3a2-1a6c0e1195ae', '4eaae194-4850-57ef-9936-90850ca10fea', 'pallet_count', 'Pallet Count', 'How many pallets or handling units are on the load. Counted at loading; printed on the loading list. Checked on unloading.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4c5de526-8647-5dad-82c1-be3324f0b72c', '4eaae194-4850-57ef-9936-90850ca10fea', 'seal_number', 'Seal Number', 'The number of the seal fixed on the vehicle or container after loading. Recorded at dispatch and checked on arrival. A broken or different seal is reported as an exception.', 10, 40, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3dedbe64-de2b-50b4-aeed-35c0e184db04', '4eaae194-4850-57ef-9936-90850ca10fea', 'planned_loading_at', 'Planned Loading At', 'The date and time the dock team expects to start loading the vehicle. Booked in the dock schedule when the load is planned; yard staff use it to assign doors and labour. It cannot be later than the planned departure.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('94debfbb-550a-5189-9cae-e5ff3022981a', '4eaae194-4850-57ef-9936-90850ca10fea', 'dispatched_at', 'Dispatched At', 'The date and time the vehicle carrying the load actually left the site. Recorded by gate staff or the driver check-out; carriers and customers use it to judge on-time delivery. Filled only once the load has been dispatched.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b6f01e50-7209-555e-86c7-37c884300e43', '4eaae194-4850-57ef-9936-90850ca10fea', 'unloaded_at', 'Unloaded At', 'The date and time the receiving site finished unloading the load at its destination. Confirmed by the receiving site on arrival; it closes the transport leg and starts goods receipt checks. Filled only after the load is unloaded.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('076248b7-8109-54c9-badb-ddad761a0390', '4eaae194-4850-57ef-9936-90850ca10fea', 'status', 'Status', 'Tells dock and transport teams where the load is in its journey, from planning to unloading. Moved forward by the dock as loading starts and the vehicle leaves, then by the receiving site on unloading. Only planned loads may still be changed; once loading begins, changes need the dock supervisor. Shipments are still being assigned and the load can be freely changed. The vehicle is at the dock and goods are being put on board. The vehicle has left the site and the load is in transit. The receiving site has taken the goods off the vehicle and the transport is complete. The load was called off before dispatch and its shipments return to planning.', 1036, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1db008d4-ce1a-5d56-92db-a7ea486466b2', '4eaae194-4850-57ef-9936-90850ca10fea', 'carrier_id', 'Carrier', 'The carrier that moves the load. Chosen when booking the vehicle. One per load. The carrier is paid per load or per trip.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('65894eb8-8977-5371-b63d-e2a9fc50d356', '4eaae194-4850-57ef-9936-90850ca10fea', 'trip_id', 'Trip', 'The trip the load travels on. Linked when the load is put on a planned trip. One trip per load; a trip may carry several loads. The trip''s route sets the sequence of stops.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e72d2b29-d602-5e4f-8803-4c49adab74ea', '4eaae194-4850-57ef-9936-90850ca10fea', 'origin_id', 'Origin', 'The place the load starts from, where the vehicle is loaded and departs. Chosen when the load is planned, usually a warehouse or distribution site, and used for route and dock planning. At most one origin per load, though many loads may start from the same location. Fixes the start of the transport leg so carriers, dock schedules and distance calculations know where to begin. Usually a warehouse.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
