VALUES ('ebecb03d-8cc6-5a74-99dd-4169d31a4d9d', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '4c5de526-8647-5dad-82c1-be3324f0b72c', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Seal Number', 'The number of the seal fixed on the vehicle or container after loading. Recorded at dispatch and checked on arrival. A broken or different seal is reported as an exception. Up to 40 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
