INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eba00fa8-0988-5784-95aa-14a68a977785', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '3dedbe64-de2b-50b4-aeed-35c0e184db04', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Planned Loading At', 'The date and time the dock team expects to start loading the vehicle. Booked in the dock schedule when the load is planned; yard staff use it to assign doors and labour. It cannot be later than the planned departure.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ebacbf5-2d6a-520d-82ab-a4220efc600f', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '94debfbb-550a-5189-9cae-e5ff3022981a', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Dispatched At', 'The date and time the vehicle carrying the load actually left the site. Recorded by gate staff or the driver check-out; carriers and customers use it to judge on-time delivery. Filled only once the load has been dispatched.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3b91474-d1d7-53e7-b0c3-305d005fa412', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', 'b6f01e50-7209-555e-86c7-37c884300e43', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Unloaded At', 'The date and time the receiving site finished unloading the load at its destination. Confirmed by the receiving site on arrival; it closes the transport leg and starts goods receipt checks. Filled only after the load is unloaded.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('65b09fc2-a608-5f11-89c3-fe0b962a123f', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '076248b7-8109-54c9-badb-ddad761a0390', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Status', 'Tells dock and transport teams where the load is in its journey, from planning to unloading. Moved forward by the dock as loading starts and the vehicle leaves, then by the receiving site on unloading. Only planned loads may still be changed; once loading begins, changes need the dock supervisor. Shipments are still being assigned and the load can be freely changed. The vehicle is at the dock and goods are being put on board. The vehicle has left the site and the load is in transit. The receiving site has taken the goods off the vehicle and the transport is complete. The load was called off before dispatch and its shipments return to planning. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5437cbbe-e316-5de9-9bcd-578499c75bec', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '1db008d4-ce1a-5d56-92db-a7ea486466b2', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Carrier', 'The carrier that moves the load. Chosen when booking the vehicle. One per load. The carrier is paid per load or per trip.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ee1aa346-daa9-59c1-bc90-6fd58d60abb1', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', '65894eb8-8977-5371-b63d-e2a9fc50d356', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Trip', 'The trip the load travels on. Linked when the load is put on a planned trip. One trip per load; a trip may carry several loads. The trip''s route sets the sequence of stops.', 150, 150, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da301357-9321-5220-8110-d51edb4a2a84', 'ca87aa13-8ed7-5dda-9eee-8e52b52fcad8', 'e72d2b29-d602-5e4f-8803-4c49adab74ea', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Origin', 'The place the load starts from, where the vehicle is loaded and departs. Chosen when the load is planned, usually a warehouse or distribution site, and used for route and dock planning. At most one origin per load, though many loads may start from the same location. Fixes the start of the transport leg so carriers, dock schedules and distance calculations know where to begin. Usually a warehouse.', 160, 160, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
