-- --------------------------------------------------------------------------
-- Route (bus_route)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5ad6d91b-1814-5431-9a77-90ba35b57912', 'Route', 'Maintain Route records', 'Create, find and maintain Route records. The list shows every Route you have access to — select a row to open it, or use New to add one. Each row is a single Route, described by 12 fields.

Id is unique: no two Route records may share the same value, and a save that would duplicate one is rejected. Name, Transport Mode and Status must be filled in before the record can be saved.

Every Route points at Carrier. Choose the linked record from the lookup on those fields rather than typing an identifier. Stop refers back to Route, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Route then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Route with no rules or workflows attached is marked Final immediately.', 'route', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3dcd461-8646-5172-b4fc-7a04d44fc40d', 'bus_route', 'Route', 'A planned path of transport stops used to move shipments or run a fleet. A route fixes the order in which stops are visited so deliveries and collections can be planned, driven and compared with what actually happened. Planned by logistics; used by dispatch and drivers. A route is made of ordered stops. A route is planned, used, and withdrawn when no longer run. Past trips keep their route. Route R-NORTH visits five depots in order from the warehouse each morning.', 'route', 'A', FALSE, FALSE, FALSE, TRUE, '5ad6d91b-1814-5431-9a77-90ba35b57912', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f9d06135-1e8e-526f-9740-207b61c5cef6', '5ad6d91b-1814-5431-9a77-90ba35b57912', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'Route', 'Shows one Route at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Carrier is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('871d9b3d-88ad-5e9e-ac33-ca38471febbc', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'id', 'Id', 'The identity of the route, constant for its life. Generated on creation; trips and shipments refer to it.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c4f7887c-127b-534d-98fe-5a4cbd2def6f', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'code', 'Code', 'The short code of the route, such as R-NORTH. Used by dispatch and drivers.', 10, 120, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0c76dae4-0943-545b-8a34-645094423739', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'name', 'Name', 'The name of the route, such as "Lyon – Milan via Turin". Shown in planning screens. Identifies the route for people, with the code.', 10, 150, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c7067b22-2701-5797-8135-c3134b44d459', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'transport_mode', 'Transport Mode', 'The means by which vehicles on the route travel between its stops. Set when the route is defined and used to choose suitable vehicles and carriers. Multimodal journeys are split into one route per mode. Travelled by truck or van on public roads. Travelled by train on a rail network. Travelled by ship between ports. Travelled by aircraft between airports.', 1056, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8fbf3ad-5444-5ec7-ad84-050a0cd0c38b', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'stop_sequence', 'Stop Sequence', 'The stops in the order they are served, between origin and destination. Lists intermediate stops, such as "Turin depot; Novara cross-dock". Origin and destination are linked separately.', 14, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2df7b10f-70ab-5be6-9e0b-140ce0825967', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'distance_km', 'Distance Km', 'The total length of the route in kilometres, measured along its stops in order. Used by planners for cost and emission estimates and for comparing alternative routes. Measured along the stops in order.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8dc69d30-e969-5f20-a51b-38961975b806', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'duration_minutes', 'Duration Minutes', 'How long the route takes from first departure to last arrival. Used for delivery-date promising and driver planning. Includes planned stop times.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4b023ea-4078-5871-8b8d-6ed2d79e1e4d', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'operating_days', 'Operating Days', 'The days the route runs, such as "Mon–Fri". Trips are created on these days. Holidays follow the calendar of the origin.', 10, 50, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('87c988a4-f0b6-5849-a1a9-142d8f2163cb', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'departure_time', 'Departure Time', 'The usual departure time, as HH:MM local time. Shown to warehouses so goods are ready. Local time of the origin.', 10, 5, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('89ab83a3-32f0-5e3a-8181-40f8e372feee', 'd3dcd461-8646-5172-b4fc-7a04d44fc40d', 'status', 'Status', 'Tells planners whether the route is being set up, in service, paused or withdrawn. Moved on by the transport planner as the route is launched, paused or discontinued. Only active routes generate trips. Still being designed and not yet in service. Operating on its schedule. Paused, for example out of season. Permanently withdrawn and no longer operated.', 1055, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
