-- --------------------------------------------------------------------------
-- Tracking Event (bus_tracking_event)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9ecc5271-d005-5eaa-a5b2-1378c86eba2b', 'Tracking Event', 'Maintain Tracking Event records', 'Create, find and maintain Tracking Event records. The list shows every Tracking Event you have access to — select a row to open it, or use New to add one. Each row is a single Tracking Event, described by 9 fields.

Id is unique: no two Tracking Event records may share the same value, and a save that would duplicate one is rejected. Event Code, Event Time, Source and Shipment must be filled in before the record can be saved.

Every Tracking Event points at Shipment and Location. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tracking Event then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tracking Event with no rules or workflows attached is marked Final immediately.', 'activity', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'bus_tracking_event', 'Tracking Event', 'A timestamped observation of how a shipment or its containers and handling units are progressing. Tracking events give the shipment''s trail: where it was and when. Because each is a fixed observation, the history can be trusted for delivery proof and delay analysis, and a correction is a new event. Created by carriers, scanners and staff; read by customer service and logistics. Each event belongs to one shipment. An event is recorded once and never changed. A mistaken one is followed by a correcting event. "Departed Leeds depot" recorded for shipment SH-1042 at 14:05 on 3 March.', 'activity', 'A', FALSE, FALSE, FALSE, TRUE, '9ecc5271-d005-5eaa-a5b2-1378c86eba2b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', '9ecc5271-d005-5eaa-a5b2-1378c86eba2b', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'Tracking Event', 'Shows one Tracking Event at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Shipment and Location are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9515eff8-21b5-5327-9f65-c667f5fb3b4c', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'id', 'Id', 'The permanent identifier of one tracking observation, never reused or altered after the event is recorded. Generated on creation; a correcting event cites it, and the shipment''s history is assembled from these identifiers. Lets a correction refer to the event it corrects. Referenced by the shipment''s history.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81992c3a-10df-5c9b-8a3e-5c3d4006c2c8', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'code', 'Code', 'The code of the event type, such as DEPARTED or DELIVERED. Gives events a consistent vocabulary across carriers. Entered by the source system; reports group by it. Read with the time and place.', 10, 120, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0452e26f-d8b4-527a-bac0-58bc3944d11b', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'event_code', 'Event Code', 'The goods were collected from the shipper. The shipment left a hub, port or terminal. The shipment reached a hub, port or terminal. The shipment is moving between two points. The shipment was held for inspection or released by customs. The shipment is on the final vehicle heading to the consignee. The shipment was handed over to the consignee, ending its journey. Something went wrong, such as damage, delay or a failed delivery attempt, and needs attention. Which milestone the event reports. Mapped from the carrier''s code; exception codes raise alerts. Carriers'' own codes are mapped to these.', 1065, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d2ecf57-9ada-544c-9c62-961d58612a24', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'event_time', 'Event Time', 'When the event happened, in the place''s local time converted to UTC. The timeline is sorted by it. Not the time the feed arrived.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cea27676-3085-5259-bbb4-aafcaa8e7266', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'description', 'Description', 'The carrier''s own wording of what happened, such as "Departed Novara hub". Shown on the shipment timeline exactly as received, beside the standard milestone. As received.', 10, 500, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b511041f-8497-5e67-bf8a-4dcf48c9f180', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'place_name', 'Place Name', 'The name of the place reported, such as "Fercam hub Novara". Shown on the timeline when no location record matches. Matched to a location where possible.', 10, 200, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f28a9819-2cda-5527-a6fc-db1d7ef8c6f3', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'source', 'Source', 'Which channel supplied the event: a carrier feed, a vehicle device or a person. Set when the event is recorded; manual events are checked before they change a delivery promise. Manual events are checked before they change a promise. The carrier''s tracking feed or API. A device on the vehicle or container. Entered by a person.', 1066, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
