VALUES ('a7066a17-3658-5a00-9c89-ab46536d63bd', '93d73a5b-25b6-5ba0-9b77-65b54f7c167f', 'location_id', 'Location', 'The known location where the event happened. Matched from the place name where possible. At most one. Empty when the place is not one of ours.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
