INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d58086cc-5050-5627-8348-7f2a0739563a', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', '9515eff8-21b5-5327-9f65-c667f5fb3b4c', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'The permanent identifier of one tracking observation, never reused or altered after the event is recorded. Generated on creation; a correcting event cites it, and the shipment''s history is assembled from these identifiers. Lets a correction refer to the event it corrects. Referenced by the shipment''s history. Must be unique: a save is rejected if another Tracking Event already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('99061c35-02e7-5c50-b4da-16e2cbefcfd1', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', '81992c3a-10df-5c9b-8a3e-5c3d4006c2c8', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Code', 'The code of the event type, such as DEPARTED or DELIVERED. Gives events a consistent vocabulary across carriers. Entered by the source system; reports group by it. Read with the time and place. Up to 120 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('df93c334-4fe7-5e91-81dc-2b524c9218e7', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', '0452e26f-d8b4-527a-bac0-58bc3944d11b', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Event Code', 'The goods were collected from the shipper. The shipment left a hub, port or terminal. The shipment reached a hub, port or terminal. The shipment is moving between two points. The shipment was held for inspection or released by customs. The shipment is on the final vehicle heading to the consignee. The shipment was handed over to the consignee, ending its journey. Something went wrong, such as damage, delay or a failed delivery attempt, and needs attention. Which milestone the event reports. Mapped from the carrier''s code; exception codes raise alerts. Carriers'' own codes are mapped to these. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d083edc9-f860-5d11-8771-8c161afbfa90', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', '9d2ecf57-9ada-544c-9c62-961d58612a24', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Event Time', 'When the event happened, in the place''s local time converted to UTC. The timeline is sorted by it. Not the time the feed arrived. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a7e77bcf-148c-5eab-9bc7-386461ab6506', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', 'cea27676-3085-5259-bbb4-aafcaa8e7266', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Description', 'The carrier''s own wording of what happened, such as "Departed Novara hub". Shown on the shipment timeline exactly as received, beside the standard milestone. As received. Up to 500 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('49ef4f4d-1bf6-5909-9709-0c33f7ddff17', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', 'b511041f-8497-5e67-bf8a-4dcf48c9f180', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Place Name', 'The name of the place reported, such as "Fercam hub Novara". Shown on the timeline when no location record matches. Matched to a location where possible. Up to 200 characters.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('33be562c-1d24-573a-b40d-c61ba72da9e8', 'a9a0c490-be6c-5c47-9fb7-e4542c1b1a98', 'f28a9819-2cda-5527-a6fc-db1d7ef8c6f3', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Source', 'Which channel supplied the event: a carrier feed, a vehicle device or a person. Set when the event is recorded; manual events are checked before they change a delivery promise. Manual events are checked before they change a promise. The carrier''s tracking feed or API. A device on the vehicle or container. Entered by a person. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
