-- --------------------------------------------------------------------------
-- Trip (bus_trip)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('83e41005-f7cb-5571-89ee-73739f398fa1', 'Trip', 'Maintain Trip records', 'Create, find and maintain Trip records. The list shows every Trip you have access to — select a row to open it, or use New to add one. Each row is a single Trip, described by 6 fields.

Id and Trip Number are unique: no two Trip records may share the same value, and a save that would duplicate one is rejected. Trip Number, Start Date and Status must be filled in before the record can be saved.

Party, Load and Trip Segment refer back to Trip, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Trip then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Trip with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a8db435a-a884-556a-b609-6ec675ae8750', 'bus_trip', 'Trip', 'A planned or completed journey made by one or more travellers, made up of transport segments and bookings. A trip groups the legs, travellers and bookings of one journey so the whole can be planned, booked, followed and paid for together, and so expenses and approvals attach to the journey rather than to loose tickets. Created by the traveller or a travel arranger; read by approvers, finance and travel support. A trip has one or more travellers, is made of segments and is paid for through bookings. A trip is planned, booked, in progress while travelling and completed on return. It may be cancelled before completion. Completed and cancelled are final. Trip TR-2026-077 takes two engineers from Leeds to Frankfurt by air on 9 March and back on 12 March.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '83e41005-f7cb-5571-89ee-73739f398fa1', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9680abbf-cb98-5f19-8939-ab85fde46af6', '83e41005-f7cb-5571-89ee-73739f398fa1', 'a8db435a-a884-556a-b609-6ec675ae8750', 'Trip', 'Shows one Trip at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be1f581f-5833-5f00-82ca-186609ea6479', 'a8db435a-a884-556a-b609-6ec675ae8750', 'id', 'Id', 'The identity of the trip, constant for its life. Generated on creation; segments and bookings refer to it. Referenced by every segment of the trip.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da778cc8-b5ef-591b-a20e-147658350b0f', 'a8db435a-a884-556a-b609-6ec675ae8750', 'trip_number', 'Trip Number', 'The number of the trip, such as TR-2026-077. Unique; quoted on expense claims and approvals. Read with the name.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3cd98846-6551-5ee3-918d-9219cdfbb6a3', 'a8db435a-a884-556a-b609-6ec675ae8750', 'name', 'Name', 'A short descriptive title for the journey, such as the purpose or destination. Entered by the traveller or arranger when planning; shown in lists and read by approvers deciding whether to authorise the trip. Read by approvers.', 10, 300, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c1668f0-3bbf-543a-958c-fcab6b1597d8', 'a8db435a-a884-556a-b609-6ec675ae8750', 'start_date', 'Start Date', 'The calendar date on which the trip begins, usually the first departure. Entered when the trip is planned and required; it must not be later than the end date and drives approval timing and reminders. Not later than the end date.', 15, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e55a7293-94f7-5f54-9aa5-3f85e328b617', 'a8db435a-a884-556a-b609-6ec675ae8750', 'end_date', 'End Date', 'The calendar date on which the trip finishes, usually the day of return. Optional while planning; once set it must not be before the start date and it fixes the length of the trip for allowances. Gives the length of the trip.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('20214290-0c39-5a5f-bd36-30ba1754ec72', 'a8db435a-a884-556a-b609-6ec675ae8750', 'status', 'Status', 'Where the trip is. Starts as PLANNED; moved as it is booked and travelled. Intended; nothing is booked. Travel and accommodation are booked. The traveller is on the journey. The trip is finished. A final state. Called off. A final state.', 1069, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
