-- --------------------------------------------------------------------------
-- Driver (bus_driver)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d54807aa-3cd8-5d4b-9060-d087cecc9c08', 'Driver', 'Maintain Driver records', 'Create, find and maintain Driver records. The list shows every Driver you have access to — select a row to open it, or use New to add one. Each row is a single Driver, described by 5 fields.

Id and Driver Code are unique: no two Driver records may share the same value, and a save that would duplicate one is rejected. Driver Code, Status and Person must be filled in before the record can be saved.

Every Driver points at Person. Choose the linked record from the lookup on those fields rather than typing an identifier. Fuel Transaction refers back to Driver, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Driver then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Driver with no rules or workflows attached is marked Final immediately.', 'contact', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'bus_driver', 'Driver', 'Represents an authorized vehicle-operating role without duplicating Person identity. Driver supplies fleet-operating eligibility and attribution; Person remains the shared identity. Fleet management, dispatch, transportation, fuel management, compliance and audit. Person is mandatory; Vehicles define assignments and FuelTransactions preserve operating-cost evidence. Driver becomes active, may suspend or become inactive, and retires while historical operations remain attributable.', 'contact', 'A', FALSE, FALSE, FALSE, TRUE, 'd54807aa-3cd8-5d4b-9060-d087cecc9c08', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4aa8dfc6-bcab-592c-8d73-e5779fd854f2', 'd54807aa-3cd8-5d4b-9060-d087cecc9c08', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'Driver', 'Shows one Driver at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Person is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('acc3fda4-7daf-55d0-bd25-cf790320aabc', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'id', 'Id', 'The identity of the driver role, independent of the person''s other roles. Identifies one transportation operating role independently of Person identity. Fleet operations, dispatch, compliance, fuel and audit. Person supplies common identity while Driver supplies operating authorization context.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('93ed88c8-3383-59d6-9289-9af9f8aaba4d', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'driver_code', 'Driver Code', 'The short code that identifies this driver in dispatch and fleet systems. Assigned when the driver is set up; used in scheduling, fuel records and reports, and unrelated to licence or person identifiers. Operational identifier for dispatch and integration. Distinct from license number and Person identifiers.', 10, 120, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41a7ed3f-3151-55cf-926c-8f9acb70f557', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'license_number', 'License Number', 'The number of the driving licence that authorises the person to drive. Entered from the licence document; checked against expiry and class. Supports operating eligibility and compliance. Jurisdiction/class/expiry may require additional governed attributes or documents.', 10, 160, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f5bd9ce6-8c45-5cdb-882a-0d3f5c955957', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'status', 'Status', 'Whether the driver is being onboarded, cleared to drive, barred for now, dormant, or gone. Moved by fleet and compliance staff; only an ACTIVE driver is offered for assignment, and past trips keep their driver. Being onboarded; not yet cleared to drive. Authorised and available for assignment. Temporarily barred, for example after an incident or lapsed qualification. Not currently driving but may return. No longer a driver; kept for history. Separates setup, active eligibility, temporary restriction, inactivity and retirement. Historical trips and fuel transactions retain Driver attribution.', 1021, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bcb4716c-4ce6-558c-a038-2d8f9ca37e35', 'fa2cec3f-5946-517b-a4c0-9a5ead8af11b', 'person_id', 'Person', 'The person who holds the driver role. Exactly one person: the role is held by a specific individual. Reuses common identity without duplicating Person data. Dispatch, contact and audit. Identity changes do not rewrite historical Driver evidence.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
