-- --------------------------------------------------------------------------
-- Fuel Transaction (bus_fuel_transaction)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('191c51d4-e14c-54f3-9d5e-99e0a778ac66', 'Fuel Transaction', 'Maintain Fuel Transaction records', 'Create, find and maintain Fuel Transaction records. The list shows every Fuel Transaction you have access to — select a row to open it, or use New to add one. Each row is a single Fuel Transaction, described by 12 fields.

Id and Transaction Number are unique: no two Fuel Transaction records may share the same value, and a save that would duplicate one is rejected. Transaction Number, Quantity, Occurred At, Status, Vehicle and Unit Of Measure must be filled in before the record can be saved.

Every Fuel Transaction points at Vehicle, Driver, Location, Unit Of Measure and Currency. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Fuel Transaction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Fuel Transaction with no rules or workflows attached is marked Final immediately.', 'fuel', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'bus_fuel_transaction', 'Fuel Transaction', 'Preserves vehicle fuel/energy consumption and cost evidence. FuelTransaction records the fleet event; Payment records settlement; Vehicle/Driver/Location provide operational attribution. Fleet management, fuel cards, efficiency analytics, accounting, fraud control and audit. Vehicle and UOM are mandatory; Driver, Location, Currency and Payment add accountability and reconciliation. Fuel transaction is recorded, then verified or reversed with history retained.', 'fuel', 'A', FALSE, FALSE, FALSE, TRUE, '191c51d4-e14c-54f3-9d5e-99e0a778ac66', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('86673ab1-b596-5be8-a2df-d83626b014e8', '191c51d4-e14c-54f3-9d5e-99e0a778ac66', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'Fuel Transaction', 'Shows one Fuel Transaction at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Vehicle, Driver, Location, Unit Of Measure and Currency are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3572ad95-0d65-5346-9acb-44c1a62fde79', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'id', 'Id', 'The identity of the fuel transaction, separate from the card or receipt number. Generated when the fill-up is recorded; verification and payment refer to it. Identifies one refueling or energy-supply event independently of payment evidence. Vehicle and quantity define operating evidence; Payment may provide financial settlement.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('702767df-5f6c-58b2-b530-39d3a1304ea2', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'transaction_number', 'Transaction Number', 'The reference of the fill-up as printed on the receipt or fuel-card statement. Entered or imported with the transaction; unique, which prevents the same fill-up being recorded twice. Operational identifier for reconciliation and integration. Distinct from Payment and supplier invoice identifiers.', 10, 120, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('968df02f-80a1-5c03-b5ed-458de79c270d', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'quantity', 'Quantity', 'The amount of fuel or energy supplied to the vehicle in this fill, stated in the transaction''s unit of measure. Taken from the pump receipt or fuel-card feed; must be positive, and consumption and efficiency reports divide distance by it. Primary consumption evidence used for efficiency and cost analysis. UnitOfMeasure defines quantity semantics.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d7d9410-55c2-5580-9539-adf2489bc5f5', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'total_amount', 'Total Amount', 'The total price paid for the fuel or energy supplied, in the transaction''s currency. Taken from the receipt or card statement and must not be negative; fleet cost allocation and payment reconciliation read it. Operating cost attributable to the refueling event. Currency defines denomination.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ab513080-ed25-54eb-9dde-2ce84996e9a5', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'occurred_at', 'Occurred At', 'The date and time at which the vehicle was actually fuelled. Captured from the pump or card feed rather than the entry time; efficiency, route and fraud checks compare it with vehicle movements. Establishes consumption chronology. Must remain attributable to vehicle/driver state at the event time.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4246185-77ba-5070-b9f5-08cfc1c069e7', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'odometer_or_meter_reading', 'Odometer Or Meter Reading', 'The vehicle''s odometer or usage-meter reading taken at the time of fuelling. Entered by the driver or read from telematics; consumption per distance and maintenance schedules depend on consecutive readings. Enables fuel efficiency and anomaly analysis. Unit/measurement type follows fleet policy.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0bfe73e9-19f0-5ccd-bdeb-ec316731e14d', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'status', 'Status', 'Whether the fuel transaction has been checked against its evidence. Set by fleet administration after comparing it with the receipt and vehicle data. Captured, not yet checked. Checked against the receipt and vehicle; costs may be allocated. A final state. Cancelled because it was wrong or duplicated; the original stays on record. A final state. Distinguishes captured, verified and explicitly reversed evidence. Reversal preserves the original event rather than deleting it.', 1026, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('001f4e74-34e8-510c-b6c8-e43822671611', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'vehicle_id', 'Vehicle', 'Exactly one vehicle: fuel is always put into a particular vehicle, which is what makes consumption trackable. Vehicle receiving the fuel or energy. Establishes asset-level consumption and cost attribution. Fleet efficiency, maintenance and reporting. Vehicle must be eligible at event time.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da317cda-1eb1-5c22-8433-c8a482a1fddb', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'driver_id', 'Driver', 'Driver performing or responsible for the fueling event. Supports accountability and fraud control. Fleet operations and audit. Optional for unattended or centrally managed fueling. Driver eligibility is evaluated at transaction time.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7d84e179-f083-5571-b393-31d6acd229a1', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'location_id', 'Location', 'Location where fueling occurred. Supplies station/depot context. Cost comparison, route analysis and audit. Optional when unavailable. Historical location remains tied to event.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4552800f-9ade-5c79-bdef-4789044d9269', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'unit_of_measure_id', 'Unit Of Measure', 'Exactly one unit, such as litres or kilowatt-hours, so the quantity has a meaning. Unit of fuel or energy quantity. Makes consumption value unambiguous. Efficiency, reporting and integration. Unit does not change after verification.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('142c8e07-8ae5-59cc-9d3b-4b7157f25992', '1d92f2aa-62ee-5377-96ec-0124a973bc7d', 'currency_id', 'Currency', 'Currency of totalAmount. Makes financial cost unambiguous. Accounting and reporting. Optional when no amount is recorded. Required when monetary amount is present under policy.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d568f710-ce79-534b-8988-01d81b62a448', '86673ab1-b596-5be8-a2df-d83626b014e8', '3572ad95-0d65-5346-9acb-44c1a62fde79', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'The identity of the fuel transaction, separate from the card or receipt number. Generated when the fill-up is recorded; verification and payment refer to it. Identifies one refueling or energy-supply event independently of payment evidence. Vehicle and quantity define operating evidence; Payment may provide financial settlement. Must be unique: a save is rejected if another Fuel Transaction already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('418d6f46-ab8c-5637-8895-afd06e13f0c2', '86673ab1-b596-5be8-a2df-d83626b014e8', '702767df-5f6c-58b2-b530-39d3a1304ea2', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Transaction Number', 'The reference of the fill-up as printed on the receipt or fuel-card statement. Entered or imported with the transaction; unique, which prevents the same fill-up being recorded twice. Operational identifier for reconciliation and integration. Distinct from Payment and supplier invoice identifiers. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Fuel Transaction already uses this value. Up to 120 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6e6bcdc-1aab-5203-972a-4f0b1a45ef48', '86673ab1-b596-5be8-a2df-d83626b014e8', '968df02f-80a1-5c03-b5ed-458de79c270d', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Quantity', 'The amount of fuel or energy supplied to the vehicle in this fill, stated in the transaction''s unit of measure. Taken from the pump receipt or fuel-card feed; must be positive, and consumption and efficiency reports divide distance by it. Primary consumption evidence used for efficiency and cost analysis. UnitOfMeasure defines quantity semantics. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a159ed3b-26c4-58c7-94d5-9777958a959d', '86673ab1-b596-5be8-a2df-d83626b014e8', '9d7d9410-55c2-5580-9539-adf2489bc5f5', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Total Amount', 'The total price paid for the fuel or energy supplied, in the transaction''s currency. Taken from the receipt or card statement and must not be negative; fleet cost allocation and payment reconciliation read it. Operating cost attributable to the refueling event. Currency defines denomination.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
