-- Message (bus_message)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ad63c116-34b0-5ac0-a2cf-2a23b530fbcf', 'Message', 'Maintain Message records', 'Create, find and maintain Message records. The list shows every Message you have access to — select a row to open it, or use New to add one. Each row is a single Message, described by 15 fields.

Id is unique: no two Message records may share the same value, and a save that would duplicate one is rejected. Message Type, Direction, Attempt Count and Status must be filled in before the record can be saved.

Delivery Attempt refers back to Message, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Message then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Message with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'bus_message', 'Message', 'An integration message envelope that keeps the payload identity, direction, correlation, processing state and delivery evidence of a message exchanged with another system. Systems exchange messages, and things go wrong. Keeping each message as a record lets operators see what was sent or received, whether it was processed and what happened on delivery, and replay it safely. Written when a message is sent or received; updated as it is processed; read by integration operators and in incident reviews. A message is delivered to IntegrationEndpoints through DeliveryAttempts. Delivery retries and corrections keep auditable evidence and never duplicate downstream business effects. An order-confirmation message received from a partner''s system and processed once. Used for event publication, message exchange, delivery, retry, reconciliation, integration operations, and audit.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, 'ad63c116-34b0-5ac0-a2cf-2a23b530fbcf', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9881ceb6-65c6-5371-9b87-b0a1959fdc4d', 'ad63c116-34b0-5ac0-a2cf-2a23b530fbcf', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'Message', 'Shows one Message at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f9a7bb75-96c8-52bf-9fdb-48f6b12fb296', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'id', 'Id', 'The identity of the message, used to detect duplicates. Generated or taken from the sender; processing uses it to be idempotent.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bd6a7eec-5f72-5858-8bff-e32de7d54973', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'occurred_at', 'Occurred At', 'When the message was created or received. Set by the integration layer; used to order messages and to measure latency.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('66d6f686-8a68-595d-86bb-40389df7b202', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'message_type', 'Message Type', 'What kind of message it is, such as "Sales order", "Despatch advice" or "pain.001 payment batch". Set by the integration layer; monitoring groups messages by it. Each type has its own mapping and format.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c085044f-e8da-55ab-ba87-90d881dd127e', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'direction', 'Direction', 'Says whether the business received this message from another system or sent it out. Set by the integration layer when the message is created; support staff filter on it when tracing a problem. Received messages are turned into business records, and sent ones come from them. Received from an external system and waiting to be turned into business records. Created by this application and sent to an external system.', 1039, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0c4cd625-a30a-5014-a987-791b1d0b6598', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'correlation_reference', 'Correlation Reference', 'The reference shared by all messages of one business transaction, such as an order number. Lets an operator follow an order or a payment run across every message about it. Set from the business record the message concerns.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f332e342-b3d8-580a-b0c0-d09609e5589f', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'external_reference', 'External Reference', 'The identifier the other system gave the message. Quoted when asking the partner about a message. Known once the other side has accepted or sent it.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f492e2e-d60f-50b2-9dff-5ae29b89c131', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'payload', 'Payload', 'The content of the message as sent or received. Opened by operators investigating a failure. Sensitive content is masked or held encrypted according to policy.', 14, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c04141d7-10bc-5207-a8f0-e64bc8f8c566', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'payload_format', 'Payload Format', 'The format of the content, such as JSON, XML, EDIFACT or CSV. Recorded so that the content can be displayed correctly. Matches the endpoint''s data format.', 10, 50, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9cf1f13f-3abd-50f8-9f3d-ff43737040eb', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'sent_at', 'Sent At', 'The time the message left the application, or arrived if it was received from outside. Stamped by the integration layer on transmission; support staff compare it with the acknowledgement time. Message lists are sorted by this time.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('24db3665-c875-5782-9385-51a01a42e5cb', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'acknowledged_at', 'Acknowledged At', 'When the other side confirmed it had the message. Recorded when an acknowledgement arrives. Not every protocol gives one.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('83e656d3-b10e-533a-b7ad-b31504214f07', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'attempt_count', 'Attempt Count', 'The number of times the system has tried to deliver or process this message. Raised by one on every try, including failed ones; operators watch it to spot messages that keep failing. Once it reaches the configured maximum the message is moved to the dead-letter queue.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b4b425db-f658-58b9-92f0-552601734222', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'error_detail', 'Error Detail', 'What went wrong on the last failed attempt. Read by the operator deciding whether to resend, correct or discard. Present while the message is failing.', 14, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2aea32b6-3bf1-5410-b899-b90ad4057069', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'status', 'Status', 'Where the message is in its delivery. Moved on by the integration layer and, for dead letters, by an operator. Failed and dead-lettered messages appear in the monitoring screen. Waiting to be sent or processed. Sent, or received and handed over for processing. Confirmed by the other side, or processed successfully. The last attempt failed; it will be retried. Given up after repeated failures; a person must act. Deliberately not delivered by an operator.', 1040, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('634fd6f1-7c9d-5ee5-b400-eb8d86ab71f3', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'endpoint_id', 'Endpoint', 'The endpoint the message went through. Set by the integration layer. One per message. Endpoint error rates are counted from its messages.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2a51caf5-27f6-5815-b4e2-9990bb720644', '5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'in_reply_to_id', 'In Reply To', 'The message this one answers, such as an acknowledgement for an order. Set by the integration layer when it matches a reply. At most one. Lets the exchange be followed as a conversation.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
