INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('76ad50ba-5654-5de5-80e2-dde723384b7d', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', 'c085044f-e8da-55ab-ba87-90d881dd127e', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Direction', 'Says whether the business received this message from another system or sent it out. Set by the integration layer when the message is created; support staff filter on it when tracing a problem. Received messages are turned into business records, and sent ones come from them. Received from an external system and waiting to be turned into business records. Created by this application and sent to an external system. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7d942bc0-fa05-509b-922a-2529ec4e4d54', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '0c4cd625-a30a-5014-a987-791b1d0b6598', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Correlation Reference', 'The reference shared by all messages of one business transaction, such as an order number. Lets an operator follow an order or a payment run across every message about it. Set from the business record the message concerns. Up to 100 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e2f3fdee-8b52-5f19-92e5-41c75efe03b8', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', 'f332e342-b3d8-580a-b0c0-d09609e5589f', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'External Reference', 'The identifier the other system gave the message. Quoted when asking the partner about a message. Known once the other side has accepted or sent it. Up to 100 characters.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f27fbc07-95ab-53fa-b9bd-75991ad78431', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '8f492e2e-d60f-50b2-9dff-5ae29b89c131', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Payload', 'The content of the message as sent or received. Opened by operators investigating a failure. Sensitive content is masked or held encrypted according to policy.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e1c9d1d8-1b90-564e-ba82-10209c0a4ffc', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', 'c04141d7-10bc-5207-a8f0-e64bc8f8c566', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Payload Format', 'The format of the content, such as JSON, XML, EDIFACT or CSV. Recorded so that the content can be displayed correctly. Matches the endpoint''s data format. Up to 50 characters.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('55e75070-93ec-5061-9b17-147daaf0ee23', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '9cf1f13f-3abd-50f8-9f3d-ff43737040eb', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Sent At', 'The time the message left the application, or arrived if it was received from outside. Stamped by the integration layer on transmission; support staff compare it with the acknowledgement time. Message lists are sorted by this time.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d0a9221-07a8-5741-bbe7-499bcee16ccf', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '24db3665-c875-5782-9385-51a01a42e5cb', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Acknowledged At', 'When the other side confirmed it had the message. Recorded when an acknowledgement arrives. Not every protocol gives one.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('26730f49-0114-5057-bc0e-a44048cfed86', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '83e656d3-b10e-533a-b7ad-b31504214f07', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Attempt Count', 'The number of times the system has tried to deliver or process this message. Raised by one on every try, including failed ones; operators watch it to spot messages that keep failing. Once it reaches the configured maximum the message is moved to the dead-letter queue. Required — the record cannot be saved while this is empty.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('31e011e9-a5b6-5af0-9b3c-bd62f8371298', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', 'b4b425db-f658-58b9-92f0-552601734222', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Error Detail', 'What went wrong on the last failed attempt. Read by the operator deciding whether to resend, correct or discard. Present while the message is failing.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cce5b9fc-dd37-5849-b452-d45bdeb19f15', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '2aea32b6-3bf1-5410-b899-b90ad4057069', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Status', 'Where the message is in its delivery. Moved on by the integration layer and, for dead letters, by an operator. Failed and dead-lettered messages appear in the monitoring screen. Waiting to be sent or processed. Sent, or received and handed over for processing. Confirmed by the other side, or processed successfully. The last attempt failed; it will be retried. Given up after repeated failures; a person must act. Deliberately not delivered by an operator. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5806bdb8-e403-59fb-9e1f-9c1908d1ea68', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '634fd6f1-7c9d-5ee5-b400-eb8d86ab71f3', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Endpoint', 'The endpoint the message went through. Set by the integration layer. One per message. Endpoint error rates are counted from its messages.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('901eddcb-8e76-5652-9341-22236f6c906f', '9881ceb6-65c6-5371-9b87-b0a1959fdc4d', '2a51caf5-27f6-5815-b4e2-9990bb720644', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'In Reply To', 'The message this one answers, such as an acknowledgement for an order. Set by the integration layer when it matches a reply. At most one. Lets the exchange be followed as a conversation.', 150, 150, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
