-- --------------------------------------------------------------------------
-- Integration Endpoint (bus_integration_endpoint)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('795be65e-3ff5-5f8b-93b1-25bc8f657f80', 'Integration Endpoint', 'Maintain Integration Endpoint records', 'Create, find and maintain Integration Endpoint records. The list shows every Integration Endpoint you have access to — select a row to open it, or use New to add one. Each row is a single Integration Endpoint, described by 14 fields.

Id and Code are unique: no two Integration Endpoint records may share the same value, and a save that would duplicate one is rejected. Code, Name, Direction, Protocol, Address, Authentication Method and Status must be filled in before the record can be saved.

Every Integration Endpoint points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Integration Endpoint then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Integration Endpoint with no rules or workflows attached is marked Final immediately.', 'database', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02f26e41-cf88-5ee1-bc35-229b128172e3', 'bus_integration_endpoint', 'Integration Endpoint', 'A logical endpoint through which messages or business events are exchanged with an internal or external system. Systems talk to each other through addresses and agreed channels. An endpoint record names one such channel and how it is used, so that deliveries can be routed, retried and audited against a known destination. Registered when a connection to another system is set up; referenced by delivery attempts; read by integration operators when diagnosing failures. Delivery attempts target an endpoint, and messages are routed to it by subscription. Delivery retries and corrections keep auditable evidence and never duplicate downstream business effects. The partner''s order-status webhook, to which the application posts "shipment.dispatched" events. Used for event publication, message exchange, delivery, retry, reconciliation, integration operations, and audit.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, '795be65e-3ff5-5f8b-93b1-25bc8f657f80', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('06cb0140-5630-5a59-a57f-6d14b737dd98', '795be65e-3ff5-5f8b-93b1-25bc8f657f80', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'Integration Endpoint', 'Shows one Integration Endpoint at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('102bfcf0-b913-5a15-9f8d-e54c08359b99', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'id', 'Id', 'The identity of the endpoint, independent of its current address. Generated on registration; subscriptions and delivery attempts refer to it, so the URL can change without breaking them.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dc4eefa9-786d-522b-aff0-15a154917e7f', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'occurred_at', 'Occurred At', 'When the endpoint was registered or last took effect. Set on registration or when its configuration changes; operators use it to tell which configuration applied to an old delivery.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41f79fa2-c66b-51d7-96b7-1d3d03912bc4', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'code', 'Code', 'The code of the endpoint, such as BANKB-SFTP-PAY. Used in configuration and in message logs. Unique.', 10, 40, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e4cffcea-880d-5b2b-b6b4-f654c35defb4', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'name', 'Name', 'A readable name for the endpoint, such as "Bank payment file upload", that people recognise in monitoring. Chosen by the integration team when registering the endpoint and shown on monitoring screens next to its code. Identifies the endpoint for people, with the code.', 10, 150, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8d748f87-175f-52ce-a5ea-84d24f02c13e', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'direction', 'Direction', 'Whether data goes out through the endpoint, comes in, or both. Set when registering it. Inbound endpoints are watched for messages that stop arriving. Data comes into the application. Data goes out of the application. Data goes both ways.', 1030, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e9e8358e-d5c4-513c-98b5-4a00ceee1f09', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'protocol', 'Protocol', 'How data travels to or from the endpoint. Set when registering it; it decides which adapter delivers the messages. Read with the address. A web service or REST API over HTTPS. Files exchanged over secure file transfer. Business documents exchanged over AS2. Messages through a queue or event broker. Messages sent or received as email. Direct access to another system''s database.', 1031, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('45b29305-715f-5de6-9ab8-6c1791d2c859', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'address', 'Address', 'Where the endpoint is reached — a URL, server and folder, or queue name. Entered by the integration administrator. Credentials are kept in a secrets store, never here.', 10, 500, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0fa7b854-598c-57b7-b14d-434df7ba5c67', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'data_format', 'Data Format', 'The format of the data exchanged, such as "ISO 20022 pain.001", "EDIFACT DESADV" or "JSON". Recorded so that a change in the partner''s format can be traced to the interfaces it affects. Message mappings depend on it.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f0c67ff5-6b3f-5625-85d9-6df971900e2d', '02f26e41-cf88-5ee1-bc35-229b128172e3', 'authentication_method', 'Authentication Method', 'No authentication, allowed only for internal endpoints carrying nothing sensitive. A secret key sent with each request. Access tokens obtained from an authorization server. A client certificate presented to prove the application''s identity, which must be renewed before it expires. An SSH key pair, typically for file transfer. A user name and password. How the application proves its identity to the endpoint. Set when registering it; the secret itself is in the secrets store. Certificate- and key-based methods need renewal before expiry.', 1029, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
