VALUES ('495336c9-74c1-52b0-b8ea-c0ccfc09e71c', '06cb0140-5630-5a59-a57f-6d14b737dd98', '102bfcf0-b913-5a15-9f8d-e54c08359b99', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Id', 'The identity of the endpoint, independent of its current address. Generated on registration; subscriptions and delivery attempts refer to it, so the URL can change without breaking them. Must be unique: a save is rejected if another Integration Endpoint already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c35bb598-02ab-5a53-81b7-b9f2175a2b15', '06cb0140-5630-5a59-a57f-6d14b737dd98', 'dc4eefa9-786d-522b-aff0-15a154917e7f', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Occurred At', 'When the endpoint was registered or last took effect. Set on registration or when its configuration changes; operators use it to tell which configuration applied to an old delivery.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bb564df2-8dc3-5aad-a972-f33403942cec', '06cb0140-5630-5a59-a57f-6d14b737dd98', '41f79fa2-c66b-51d7-96b7-1d3d03912bc4', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Code', 'The code of the endpoint, such as BANKB-SFTP-PAY. Used in configuration and in message logs. Unique. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Integration Endpoint already uses this value. Up to 40 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('45928e23-171e-546a-9799-cf57f11c597f', '06cb0140-5630-5a59-a57f-6d14b737dd98', 'e4cffcea-880d-5b2b-b6b4-f654c35defb4', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Name', 'A readable name for the endpoint, such as "Bank payment file upload", that people recognise in monitoring. Chosen by the integration team when registering the endpoint and shown on monitoring screens next to its code. Identifies the endpoint for people, with the code. Required — the record cannot be saved while this is empty. Up to 150 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2b1342b3-4245-5ae7-ac70-87ea8b5289da', '06cb0140-5630-5a59-a57f-6d14b737dd98', '8d748f87-175f-52ce-a5ea-84d24f02c13e', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Direction', 'Whether data goes out through the endpoint, comes in, or both. Set when registering it. Inbound endpoints are watched for messages that stop arriving. Data comes into the application. Data goes out of the application. Data goes both ways. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3a64a97f-651a-544f-93ab-eee23e5a4aad', '06cb0140-5630-5a59-a57f-6d14b737dd98', 'e9e8358e-d5c4-513c-98b5-4a00ceee1f09', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Protocol', 'How data travels to or from the endpoint. Set when registering it; it decides which adapter delivers the messages. Read with the address. A web service or REST API over HTTPS. Files exchanged over secure file transfer. Business documents exchanged over AS2. Messages through a queue or event broker. Messages sent or received as email. Direct access to another system''s database. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
