VALUES ('6fee96f2-37fe-5c1c-8a76-4c67e636af31', 'bus_party_status', 'Party Status', 'The values of party status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'f8e7fa2a-649d-5117-9339-b693618480d4', 'U', TRUE, 'system', 'system', NOW(), NOW())
