VALUES ('e6786fda-a544-5512-bb30-3062e9225b26', 'bus_contact_point_channel', 'Contact Point Channel', 'The values of contact point channel, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '825ddab8-034b-5b70-a5f1-adc5bf01e8d1', 'U', TRUE, 'system', 'system', NOW(), NOW())
