VALUES ('9dae858d-51fd-5d6b-aaac-4dec4879edab', 'bus_task_task_type', 'Task Task Type', 'The values of task task type, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '2d9bcee1-4009-5f92-a633-00a19ba4c620', 'U', TRUE, 'system', 'system', NOW(), NOW())
