VALUES ('4401aade-6798-5972-ab44-d4506e88f427', 'bus_sales_order_status', 'Sales Order Status', 'The values of sales order status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '06bf4907-30e4-590e-83bb-4db4114f8fee', 'U', TRUE, 'system', 'system', NOW(), NOW())
