VALUES ('2cbb145a-f2e7-5c4b-9792-c517e76a8a3d', 'bus_delivery_attempt_result', 'Delivery Attempt Result', 'The values of delivery attempt result, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'dd36c972-f1ba-5b3a-87ee-cecc524838ec', 'U', TRUE, 'system', 'system', NOW(), NOW())
