VALUES ('1cdd3109-a5b2-585f-945d-5b6b1cfbddb8', 'bus_driver_status', 'Driver Status', 'The values of driver status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '2d1b612c-7208-59b6-afe5-f570265f11eb', 'U', TRUE, 'system', 'system', NOW(), NOW())
