-- --------------------------------------------------------------------------
-- Shipment Line (bus_shipment_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'bus_shipment_line', 'Shipment Line', 'Line-level logistics execution connecting commercial demand to physical transport and inventory evidence. ShipmentLine says what quantity moved in logistics; InventoryMovement says what happened to stock. Outbound fulfillment, inbound transport, transfers, returns, carrier operations, claims, and audit. Shipment supplies logistics context; order lines supply demand/commitment; InventoryMovement supplies stock effects. Planned → dispatched → delivered or exception/cancellation according to parent shipment. Quantity or source-line changes revalidate allocation, inventory, receiving, fulfillment, and delivery workflows.', 'truck', 'A', FALSE, FALSE, FALSE, TRUE, 'ab040334-78c5-5316-9ee9-7b16736a368b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e7c10e7-c46d-5b78-86bb-788f58347efa', 'ab040334-78c5-5316-9ee9-7b16736a368b', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'Shipment Line', 'Shows one Shipment Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Shipment, Product, Unit Of Measure and Sales Order Line are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('10049b5e-25ea-5529-9a61-027493b8bded', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'id', 'Id', 'The stable identity of one product quantity line on a shipment, constant for its life. Generated on creation; claims, tracking events and inventory movements refer to it even when line numbers are renumbered. Identifies a logistics quantity independently of order and inventory events. Bridges order lines and inventory movements.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e2d4ad5-3c59-568a-bd41-225f55721055', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'line_number', 'Line Number', 'The position of the line on the shipment. Human-facing reference for shipped material. Packing, carrier documents, delivery, and audit. Unique within Shipment.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f21ef851-7e34-54af-8287-63d8b050c54b', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'planned_quantity', 'Planned Quantity', 'The quantity of the product that the shipment is planned to carry on this line. Set when the shipment is planned from order demand; used for allocation, packing and capacity, and compared with what is dispatched. Defines intended transport quantity before dispatch. Must be compatible with product/UOM and eligible source demand.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fe621d28-8d8d-5633-8153-101a45e07cf1', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'dispatched_quantity', 'Dispatched Quantity', 'The quantity physically handed to the carrier or loaded for transport, starting at zero. Updated at dispatch by warehouse staff; it must reconcile with the issue or transfer movements and drives order fulfilment. Records logistics execution quantity. Must reconcile with attributable issue/transfer movements.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e562df9-d927-5ebe-ac78-39d019bea50a', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'delivered_quantity', 'Delivered Quantity', 'The quantity confirmed delivered at the destination, starting at zero until delivery evidence arrives. Recorded from delivery confirmation; the gap from dispatched quantity raises shortage claims, though delivery does not post stock. Records transport completion at line level. Delivery evidence does not itself post inventory or settle invoices.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0aa35a0a-68fb-5ff0-a7f4-0736990719fe', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'shipment_id', 'Shipment', 'Each line belongs to exactly one shipment and goes with it. Parent logistics movement. Supplies route, carrier, type, and lifecycle. Transport execution. Controls dispatch and delivery progression.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9aad520e-96f8-52be-84a6-fd8cbb548d95', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'product_id', 'Product', 'Each line carries one product. Product being transported. Identifies material represented by quantities. Fulfillment and inventory traceability. Must reconcile with source order and inventory events.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6326d956-023c-5071-8a7c-f56843a3beab', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'unit_of_measure_id', 'Unit Of Measure', 'Unit qualifying shipment quantities. Gives quantity semantics. Conversion, fulfillment, and audit. Optional when inherited unambiguously. Must be compatible with product and source transaction.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('00bd57d7-0e1a-50bb-bf20-05783be52bb1', '07d84546-f9b3-5eb2-9ebb-86b35be5ed1c', 'sales_order_line_id', 'Sales Order Line', 'Outbound demand fulfilled by this line. Preserves exact sales fulfillment provenance. Order fulfillment and customer service. Optional for non-sales shipments. Delivered/dispatched quantities contribute only through governed fulfillment.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
