VALUES ('14206844-d986-5fa0-bac8-fe3f5cefc896', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '1e2d4ad5-3c59-568a-bd41-225f55721055', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Line Number', 'The position of the line on the shipment. Human-facing reference for shipped material. Packing, carrier documents, delivery, and audit. Unique within Shipment. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
