INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ae1abf7-0cf6-57b6-8991-68a9ee298fbc', '0e7c10e7-c46d-5b78-86bb-788f58347efa', 'f21ef851-7e34-54af-8287-63d8b050c54b', '3e5b7c9b-720f-585a-a228-03e43c733f09', 'Planned Quantity', 'The quantity of the product that the shipment is planned to carry on this line. Set when the shipment is planned from order demand; used for allocation, packing and capacity, and compared with what is dispatched. Defines intended transport quantity before dispatch. Must be compatible with product/UOM and eligible source demand. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('78f7fef9-9bfc-58a0-99ea-8c8606468427', '0e7c10e7-c46d-5b78-86bb-788f58347efa', 'fe621d28-8d8d-5633-8153-101a45e07cf1', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Dispatched Quantity', 'The quantity physically handed to the carrier or loaded for transport, starting at zero. Updated at dispatch by warehouse staff; it must reconcile with the issue or transfer movements and drives order fulfilment. Records logistics execution quantity. Must reconcile with attributable issue/transfer movements. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f59efbf8-8785-5d69-8920-20c7e94c5510', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '0e562df9-d927-5ebe-ac78-39d019bea50a', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Delivered Quantity', 'The quantity confirmed delivered at the destination, starting at zero until delivery evidence arrives. Recorded from delivery confirmation; the gap from dispatched quantity raises shortage claims, though delivery does not post stock. Records transport completion at line level. Delivery evidence does not itself post inventory or settle invoices. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ba7f779d-5b81-5d4a-b0dd-4bdb2a923576', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '0aa35a0a-68fb-5ff0-a7f4-0736990719fe', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Shipment', 'Each line belongs to exactly one shipment and goes with it. Parent logistics movement. Supplies route, carrier, type, and lifecycle. Transport execution. Controls dispatch and delivery progression. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('810a42a5-a678-5043-8fe8-e383cb8a7e7d', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '9aad520e-96f8-52be-84a6-fd8cbb548d95', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Product', 'Each line carries one product. Product being transported. Identifies material represented by quantities. Fulfillment and inventory traceability. Must reconcile with source order and inventory events. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f8ac13d-0090-5ba0-b481-4b034a4a3cfa', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '6326d956-023c-5071-8a7c-f56843a3beab', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Unit Of Measure', 'Unit qualifying shipment quantities. Gives quantity semantics. Conversion, fulfillment, and audit. Optional when inherited unambiguously. Must be compatible with product and source transaction.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('803dc7ac-c010-56f7-9d14-49588d5c0b40', '0e7c10e7-c46d-5b78-86bb-788f58347efa', '00bd57d7-0e1a-50bb-bf20-05783be52bb1', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Sales Order Line', 'Outbound demand fulfilled by this line. Preserves exact sales fulfillment provenance. Order fulfillment and customer service. Optional for non-sales shipments. Delivered/dispatched quantities contribute only through governed fulfillment.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
