-- --------------------------------------------------------------------------
-- Stop (bus_stop)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('55d80773-8705-5a50-8888-15da4d37e035', 'bus_stop', 'Stop', 'Represents one ordered operational point on a transportation Route. Route defines the journey; Stop defines sequence and activity at a reusable Location. Transportation, fleet, logistics, dispatch, ETA planning and audit. Route and Location are mandatory; planned times support scheduling while tracking events provide actual evidence. A delivery Route has origin, three delivery Stops and a fuel Stop before its final destination.', 'map-pin', 'A', FALSE, FALSE, FALSE, TRUE, '5ad6d91b-1814-5431-9a77-90ba35b57912', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('50058ea8-128e-53f8-b227-5ae1fbe1660f', '5ad6d91b-1814-5431-9a77-90ba35b57912', '55d80773-8705-5a50-8888-15da4d37e035', 'Stop', 'Shows one Stop at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Route and Location are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b7daafc1-d5ae-57f5-9491-fb4970f136d1', '55d80773-8705-5a50-8888-15da4d37e035', 'id', 'Id', 'The stable identity of one stop on a route, independent of the location it visits. Generated on creation; dispatch, tracking and audit refer to it, and it stays the same when the stop is resequenced. Identifies one ordered route point independently of Location identity. Location states where; Stop states route sequence and operational purpose.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8d07125-f454-5bce-9343-1a50112aece5', '55d80773-8705-5a50-8888-15da4d37e035', 'sequence_number', 'Sequence Number', 'The order in which the stop is visited along its route, starting from the first stop. Assigned by the route planner; it should be unique within a route and is changed when stops are reordered. Defines planned route progression. Unique within a Route under ordinary policy.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a62d19a-840c-5a53-9b6f-11a3908a6a54', '55d80773-8705-5a50-8888-15da4d37e035', 'stop_type', 'Stop Type', 'The purpose of the stop: what the vehicle or driver is expected to do there. Chosen by the route planner; it drives dispatch instructions, ETA planning and reporting, and shipments may refine the activity further. The point where the route begins and the vehicle starts its journey. A point where goods or passengers are collected onto the vehicle. A point where goods are handed over to the receiver. A point where a service is performed, such as an installation or inspection. A point passed through to shape the route, with no loading or service. A point where the vehicle stops to refuel or recharge. A point where the driver stops for a mandatory or planned rest. The point where the route ends and the journey is complete. Any purpose not covered by the other types, described in dispatch notes. Explains expected activity at the route point. Specific shipments or tasks may further refine activity.', 1061, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e989462f-8848-5ea9-aec5-41442aa4d760', '55d80773-8705-5a50-8888-15da4d37e035', 'planned_arrival_at', 'Planned Arrival At', 'The date and time the vehicle is scheduled to arrive at this stop. Set by the route planner and used for dispatch, customer ETA messages and punctuality analysis; actual arrival is recorded separately. Supports schedule and ETA expectations. Actual tracking events remain separate evidence.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4de7d573-da75-51df-aac4-862f36c3e343', '55d80773-8705-5a50-8888-15da4d37e035', 'planned_departure_at', 'Planned Departure At', 'The date and time the vehicle is scheduled to leave this stop after loading, unloading or service. Set by the planner to define dwell time and capacity; it must not be earlier than the planned arrival when both exist. Defines service window or dwell plan. Must not precede plannedArrivalAt when both are supplied.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('026efc9d-12e5-53c3-bac9-32d612a0ac14', '55d80773-8705-5a50-8888-15da4d37e035', 'route_id', 'Route', 'The route the stop is part of. Exactly one route; a stop belongs to the route it sequences. Supplies ordered transportation context. Route planning, dispatch and reporting. sequenceNumber is interpreted within this Route.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dc7f6381-cade-50f2-804c-c7d0e718f616', '55d80773-8705-5a50-8888-15da4d37e035', 'location_id', 'Location', 'Each stop is at one location, so the vehicle''s destination is unambiguous. Physical or logical location of the Stop. Separates reusable Location master from route-specific occurrence. Navigation, dispatch and reporting. Location changes do not rewrite completed route history.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
