-- Trip Segment (bus_trip_segment)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'bus_trip_segment', 'Trip Segment', 'One leg of a trip between an origin and a destination by a mode of transport. Segments give the route its detail, so each flight, train or drive can be booked, timed and followed separately, and delays can be seen on the leg where they happened. Added by the traveller or arranger; read by travel support and the traveller. A segment belongs to one trip, runs between two locations and may use a vehicle. A segment is planned, booked, in progress while travelling and completed on arrival. It may be cancelled. Completed and cancelled are final. The second leg of trip TR-2026-077 is a flight from Manchester to Frankfurt departing 07:10.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '83e41005-f7cb-5571-89ee-73739f398fa1', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('78ef3ff5-3eb9-52ab-9d83-dcce53b45b9f', '83e41005-f7cb-5571-89ee-73739f398fa1', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'Trip Segment', 'Shows one Trip Segment at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Trip and Vehicle are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('520ec384-f6e7-54cd-8212-40ec97324c90', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'id', 'Id', 'The permanent identifier of one leg of a trip, unchanged when its times or mode are revised. Generated on creation; bookings and tickets for the leg refer to it so they can be matched to the right part of the journey. Referenced by bookings of the leg.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('40b54748-17be-5bb6-9efb-7514ffe5fb3e', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'sequence', 'Sequence', 'The position of the leg in the journey. Entered in order; the trip follows the sequence. Read with the trip.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6889e5c1-09bb-521c-bace-49bc1ff286ee', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'mode', 'Mode', 'The means of transport used to travel the leg, such as flight, train, road or sea. Chosen when the leg is planned; it decides what must be booked, which supplier is used and what expenses to expect. Travel by aircraft, normally needing a flight booking and airport time. Travel by train, booked as a rail ticket or pass. Travel by car, van or truck on public roads, whether driven or hired. Travel by ferry or ship across water. Travel by bus or coach on a scheduled or chartered service. Travel on foot, usually a short transfer needing no booking. Any means of transport not covered by the standard modes, described in the booking. Decides what must be booked.', 1067, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('20684e2c-2a8f-52eb-816b-a5ff89146841', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'departure_at', 'Departure At', 'Entered from the booking; arrivals are measured from it. Not later than arrival. Records when the departure event occurred. It establishes chronology, supports auditability, and helps coordinate related lifecycle and process activities.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('65f00179-ec1a-549f-9f02-d77c08a02682', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'arrival_at', 'Arrival At', 'Entered from the booking and updated on arrival; must not be before departure. Gives the leg''s duration. Records when the arrival event occurred. It establishes chronology, supports auditability, and helps coordinate related lifecycle and process activities.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('986e6047-a8a9-5941-acbf-5e3a47482e36', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'status', 'Status', 'How far the leg has progressed, from planning through booking and travel to completion. Starts as PLANNED; moved as the leg is booked, started and finished, or called off before it ends. Intended as part of the route but nothing is booked yet. Tickets or reservations are confirmed for the leg. The traveller is making the journey on this leg now. The leg has been travelled to its destination. A final state. The leg was called off and will not be travelled. A final state.', 1068, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d0a9372-fe88-58d0-b8d8-48974975cbaa', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'trip_id', 'Trip', 'The trip the leg belongs to. Set when the segment is added. Exactly one trip; a leg cannot stand alone. Places the leg in the journey.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1f7ddc88-5364-5b0b-84b7-c000156f4d91', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'origin_id', 'Origin', 'A leg starts at one location; a journey with a change is two legs. The place the leg starts from. Chosen when planned. Where the traveller begins this leg.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4625d70-af95-5d43-b1c0-1461026b53ac', 'e2d95cd0-5272-54aa-99b5-aed742d59aa6', 'vehicle_id', 'Vehicle', 'The vehicle used for the leg, if known. Chosen for owned or hired vehicles. At most one vehicle. Links the leg to the vehicle record.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
