VALUES ('f3caf886-c6cf-5044-aceb-397d87ad3950', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', 'e7263cfe-92f7-525a-8274-f67d8dd8f23b', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Price Determined At', 'The date and time the unit price for this line was fixed. Stamped when pricing runs and kept, so a later price list change does not alter what the customer was quoted. Used to explain which price list was in force.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e096d335-c51d-5f51-9b80-5e179f6b12c9', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '79e110b5-a0a2-5475-8db0-d48625d3d27e', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Unit Of Measure', 'The unit the quantity is expressed in. Defaults to the product''s selling unit. At most one unit; empty uses the default. Makes the quantity unambiguous.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9414b813-eec8-5c26-b1a4-5a32c1e0fd1a', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '56aa9f4e-0b1f-59ca-bb43-373463bb73fa', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Sales Order', 'Links a sales order line to sales order, the sales order it relates to. Chosen from the existing sales order records when the sales order line is created or edited. A sales order line has exactly one sales order in this role. Lets the sales order line be found from, and reported with, its sales order. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
